`timescale 1ns / 1ps

// Self-checking testbench for ofdm_axi_lite (fpga/ofdm_axi_lite.v).
//
// Runs exactly the sequence main.c performs, then reads the frame back over
// AXI and checks it against a hard-coded copy of the golden frame. The golden
// values are generated by testbenches/tb_full.v's model (random payload
// 0xA5C3_0F1E_9B47_D268_3C5A_E1F0_7788_B2D4); regenerate them if the OFDM
// datapath changes.
//
// Covers:
//   - ID register sanity check
//   - CTRL/QPSK writes, STATUS polling for done
//   - all 320 frame words read back bit-exact over the AXI read channel
//   - re-run: CTRL=0 must clear done so a second frame can be produced
//
// No external files are needed; the expected frame is embedded below.

module tb_ofdm_axi_lite;

    localparam [127:0] BITS =
        128'hA5C3_0F1E_9B47_D268_3C5A_E1F0_7788_B2D4;
    localparam N_WORDS  = 320;
