    // ------------------------------------------------------------------
    // AXI4-Lite bus functional model
    // ------------------------------------------------------------------
    task axi_write(input [11:0] a, input [31:0] d);
        begin
            @(posedge clk);
            awaddr <= a; wdata <= d; awvalid <= 1; wvalid <= 1;
            @(posedge clk);
            while (!(awready && wready)) @(posedge clk);
            awvalid <= 0; wvalid <= 0;
            bready <= 1;
            @(posedge clk);
            while (!bvalid) @(posedge clk);
            bready <= 0;
            @(posedge clk);
        end
    endtask

    task axi_read(input [11:0] a, output [31:0] d);
        begin
            @(posedge clk);
            araddr <= a; arvalid <= 1;
            @(posedge clk);
            while (!arready) @(posedge clk);
            arvalid <= 0; rready <= 1;
            @(posedge clk);
            while (!rvalid) @(posedge clk);
            d = rdata;
            rready <= 0;
            @(posedge clk);
        end
    endtask

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    initial begin
        alt[0] = 32'h11111111; alt[1] = 32'h22222222;
        alt[2] = 32'h33333333; alt[3] = 32'h44444444;

        repeat (4) @(posedge clk);
        aresetn = 1'b1;
        repeat (2) @(posedge clk);

        // --- ID register ---
        axi_read(12'h018, id_val);
        if (id_val !== 32'h0FDA0001) begin
            $display("[FAIL] ID = 0x%08x, expected 0x0FDA0001", id_val);
            error_count = error_count + 1;
        end else
            $display("[PASS] ID register = 0x%08x", id_val);

        // --- run one frame ---
        axi_write(12'h000, 32'd0);
        axi_write(12'h008, BITS[ 31:  0]);
        axi_write(12'h00C, BITS[ 63: 32]);
        axi_write(12'h010, BITS[ 95: 64]);
        axi_write(12'h014, BITS[127: 96]);
        axi_write(12'h000, 32'd1);

        polls  = 0;
        st     = 32'd0;
        while (!(st & 32'h1)) begin
            axi_read(12'h004, st);
            polls = polls + 1;
            if (polls > POLL_MAX) begin
                $display("[FAIL] timeout waiting for STATUS.done");
                error_count = error_count + 1;
                polls = POLL_MAX;
            end
        end
        if (polls <= POLL_MAX)
            $display("[PASS] STATUS.done asserted after %0d polls", polls);

        // --- read the frame back ---
        for (i = 0; i < N_WORDS; i = i + 1) begin
            axi_read(FRAME_LO + i * 4, val);
            if (val !== golden[i]) begin
                if (error_count < 10)
                    $display("[FAIL] frame word %0d (addr 0x%03x): got 0x%08x expected 0x%08x",
                             i, FRAME_LO + i * 4, val, golden[i]);
                error_count = error_count + 1;
            end
        end
        if (error_count == 0)
            $display("[PASS] all %0d frame words read back bit-exact over AXI", N_WORDS);
        else
            $display("[FAIL] frame readback mismatch");

        // --- re-run must clear done and produce a different frame ---
        // Word 0 belongs to symbol 0, which is the ZC sync symbol and does not
        // depend on the payload, so probe the last word of symbol 3 instead.
        axi_read(FRAME_LO + (N_WORDS - 1) * 4, w0);
        axi_write(12'h000, 32'd0);
        axi_write(12'h008, alt[0]);
        axi_write(12'h00C, alt[1]);
        axi_write(12'h010, alt[2]);
        axi_write(12'h014, alt[3]);
        axi_write(12'h000, 32'd1);

        polls2 = 0;
        st     = 32'd0;
        while (!(st & 32'h1)) begin
            axi_read(12'h004, st);
            polls2 = polls2 + 1;
            if (polls2 > POLL_MAX) begin
                $display("[FAIL] re-run timed out (done never re-asserted)");
                error_count = error_count + 1;
                polls2 = POLL_MAX;
            end
        end
        axi_read(FRAME_LO + (N_WORDS - 1) * 4, val);
        if (val === w0) begin
            $display("[FAIL] re-run produced the same frame; CTRL=0 did not clear done");
            error_count = error_count + 1;
        end else
            $display("[PASS] re-run cleared done and regenerated the frame");
        if (polls2 <= POLL_MAX)
            $display("[INFO] re-run done after %0d polls", polls2);

        $display("========================================");
        if (error_count == 0) $display("   ALL OFDM AXI-LITE TESTS PASSED");
        else                  $display("   ALL OFDM AXI-LITE TESTS FAILED: %0d error(s)",
                                         error_count);
        $display("========================================");
        $finish;
    end

    initial begin
        #(10 * (POLL_MAX + 100));
        $display("[FAIL] global timeout");
        $finish;
    end

endmodule